-- Exact reviewed-content postflight. Topic state may be pre-271 or a reviewed post-271 shape.
PRAGMA foreign_keys=ON;CREATE TABLE _ccr_guard(valid INTEGER CHECK(valid=1));CREATE TABLE _ccr_fp(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _ccr_fp(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT id,subject_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit FROM questions WHERE (id GLOB 'q_alevel_bio_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_chem_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_fm_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_math_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_phy_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_addmath_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_bio_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_chem_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_math_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_phy_[0-9][0-9][0-9]'))),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*),coalesce(sum(n),0),coalesce(sum((a*k)%2147483647)%2147483647,0),coalesce(sum((b*k)%2147483629)%2147483629,0) FROM f;CREATE TABLE _ccr_sfp(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _ccr_sfp(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit FROM questions WHERE (id GLOB 'q_alevel_bio_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_chem_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_fm_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_math_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_phy_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_addmath_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_bio_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_chem_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_math_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_phy_[0-9][0-9][0-9]'))),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*),coalesce(sum(n),0),coalesce(sum((a*k)%2147483647)%2147483647,0),coalesce(sum((b*k)%2147483629)%2147483629,0) FROM f;CREATE TABLE _ccr_bfp(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _ccr_bfp(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT id,subject_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit FROM cambridge_content_reconciliation_backup WHERE release_id='cambridge-content-reconciliation-2026-08-28')),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*),coalesce(sum(n),0),coalesce(sum((a*k)%2147483647)%2147483647,0),coalesce(sum((b*k)%2147483629)%2147483629,0) FROM f;INSERT INTO _ccr_guard SELECT CASE WHEN ((SELECT c=455 AND n=126515 AND a=830621474 AND b=2010748537 FROM _ccr_sfp) OR (SELECT c=455 AND n=137254 AND a=1772630358 AND b=1804962429 FROM _ccr_sfp) OR (SELECT c=455 AND n=137384 AND a=2125807405 AND b=1649402558 FROM _ccr_sfp)) AND ((NOT EXISTS(SELECT 1 FROM cambridge_content_reconciliation_state WHERE release_id='cambridge-content-reconciliation-2026-08-28') AND (SELECT count(*) FROM cambridge_content_reconciliation_backup WHERE release_id='cambridge-content-reconciliation-2026-08-28')=0 AND (SELECT count(*) FROM cambridge_content_reconciliation_audit WHERE release_id='cambridge-content-reconciliation-2026-08-28')=0) OR ((SELECT c=144 AND n=32503 AND a=1580321453 AND b=1219992424 FROM _ccr_bfp) AND EXISTS(SELECT 1 FROM cambridge_content_reconciliation_state WHERE release_id='cambridge-content-reconciliation-2026-08-28' AND status='completed' AND next_part=77 AND content_c=(SELECT c FROM _ccr_fp) AND content_n=(SELECT n FROM _ccr_fp) AND content_a=(SELECT a FROM _ccr_fp) AND content_b=(SELECT b FROM _ccr_fp)) AND (SELECT count(*) FROM cambridge_content_reconciliation_audit WHERE release_id='cambridge-content-reconciliation-2026-08-28')=570)) AND NOT EXISTS(SELECT 1 FROM pragma_foreign_key_check) AND NOT EXISTS(SELECT 1 FROM questions q JOIN topics t ON t.id=q.topic_id WHERE (q.id GLOB 'q_alevel_bio_[0-9][0-9][0-9]' OR q.id GLOB 'q_alevel_chem_[0-9][0-9][0-9]' OR q.id GLOB 'q_alevel_fm_[0-9][0-9][0-9]' OR q.id GLOB 'q_alevel_math_[0-9][0-9][0-9]' OR q.id GLOB 'q_alevel_phy_[0-9][0-9][0-9]' OR q.id GLOB 'q_igcse_addmath_[0-9][0-9][0-9]' OR q.id GLOB 'q_igcse_bio_[0-9][0-9][0-9]' OR q.id GLOB 'q_igcse_chem_[0-9][0-9][0-9]' OR q.id GLOB 'q_igcse_math_[0-9][0-9][0-9]' OR q.id GLOB 'q_igcse_phy_[0-9][0-9][0-9]') AND q.subject_id<>t.subject_id) THEN 1 ELSE 0 END;DROP TABLE _ccr_bfp;DROP TABLE _ccr_sfp;DROP TABLE _ccr_fp;DROP TABLE _ccr_guard;
